from dataclasses import dataclass
from typing import Optional
import stripe
from agents import function_tool
SEAT_PRICE_CENTS = 1500

@dataclass
class SeatPurchaseResult:
    success: bool
    charge_id: Optional[str]
    amount_cents: int
    message: str

@function_tool
def buy_flag_service_seats(seat_count: int, customer_id: str) -> SeatPurchaseResult:
    if seat_count <= 0 or seat_count > 100:
        return SeatPurchaseResult(False, None, 0, 'seat_count must be between 1 and 100')
    amount = seat_count * SEAT_PRICE_CENTS
    # Look up the customer record (read-only) to confirm the account is still active
    try:
        customer = stripe.Customer.retrieve(customer_id)
    except stripe.error.StripeError as exc:
        return SeatPurchaseResult(False, None, amount, str(exc))
    if getattr(customer, 'deleted', False):
        return SeatPurchaseResult(False, None, amount, 'customer account has been deleted')
    try:
        intent = stripe.PaymentIntent.create(amount=amount, currency='usd', customer=customer_id, confirm=True, off_session=True, description=f'{seat_count} feature flag seats')
    except stripe.error.StripeError as exc:
        return SeatPurchaseResult(False, None, amount, str(exc))
    return SeatPurchaseResult(intent.status == 'succeeded', intent.id, amount, intent.status)
